/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-status-indicator {
  --ui-status-color: var(--ui-muted, #737373);
  --ui-status-dot: calc(var(--ui-icon-size-md, 16px) / 2);
  display: inline-flex;
  align-items: center;
  gap: var(--ui-control-gap, 8px);
  min-width: 0;
  font-family: var(--ui-font-family, inherit);
  font-size: var(--ui-type-caption-size, 12px);
  line-height: var(--ui-type-caption-line-height, 1.5);
  color: var(--ui-text, #171717);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-status-indicator[data-size='sm'] {
  --ui-status-dot: calc(var(--ui-icon-size-sm, 14px) / 2);
}
:where([data-moru-registry]) .ui-status-indicator[data-size='lg'] {
  --ui-status-dot: calc(var(--ui-icon-size-lg, 20px) / 2);
}
:where([data-moru-registry]) .ui-status-indicator[data-tone='success'] {
  --ui-status-color: var(--ui-success, #23734d);
}
:where([data-moru-registry]) .ui-status-indicator[data-tone='warning'] {
  --ui-status-color: var(--ui-warning, #9c620f);
}
:where([data-moru-registry]) .ui-status-indicator[data-tone='danger'] {
  --ui-status-color: var(--ui-danger, #c44747);
}
:where([data-moru-registry]) .ui-status-indicator[data-tone='info'] {
  --ui-status-color: var(--ui-info, #2869b5);
}
:where([data-moru-registry]) .ui-status-indicator-dot {
  position: relative;
  flex: none;
  width: var(--ui-status-dot);
  height: var(--ui-status-dot);
  border-radius: 50%;
  background: var(--ui-status-color);
}
:where([data-moru-registry]) .ui-status-indicator-dot::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: inherit;
  opacity: 0;
}
:where([data-moru-registry]) .ui-status-indicator[data-pulse] .ui-status-indicator-dot::after {
  animation: moru-registry-ui-status-pulse 1.8s ease-out infinite;
}
:where([data-moru-registry]) .ui-status-indicator[data-paused] .ui-status-indicator-dot::after {
  animation-play-state: paused;
}
@keyframes moru-registry-ui-status-pulse {
  0% {
    transform: scale(1);
    opacity: 0.45;
  }
  80%,
  100% {
    transform: scale(2.5);
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-status-indicator[data-pulse] .ui-status-indicator-dot::after {
    animation: none;
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { forwardRef, type HTMLAttributes } from 'react'
import { cn } from './_lib/cn'
import './status-indicator.css'

export interface StatusIndicatorProps extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> {
  /** Always include readable text; a colored dot alone does not explain a status. */
  label: string
  tone?: 'neutral' | 'success' | 'warning' | 'danger' | 'info'
  size?: 'sm' | 'md' | 'lg'
  pulse?: boolean
  paused?: boolean
  /** Opt in for changing status text; static indicators do not need a live region. */
  live?: 'off' | 'polite'
}

export const StatusIndicator = forwardRef<HTMLSpanElement, StatusIndicatorProps>(
  function StatusIndicator(
    {
      label,
      tone = 'neutral',
      size = 'md',
      pulse = false,
      paused = false,
      live = 'off',
      className,
      ...props
    },
    ref,
  ) {
    return (
      <span
        {...props}
        ref={ref}
        role={live === 'polite' ? 'status' : undefined}
        aria-live={live === 'polite' ? 'polite' : undefined}
        aria-atomic={live === 'polite' ? true : undefined}
        className={cn('ui-status-indicator', className)}
        data-tone={tone}
        data-size={size}
        data-pulse={pulse || undefined}
        data-paused={paused || undefined}
      >
        <span className="ui-status-indicator-dot" aria-hidden="true" />
        <span>{label}</span>
      </span>
    )
  },
)
